set transaction read only;
-- =====================================================================================================
-- SEO content repair 2026-11 (audit fixes F5 internal links + F14 fee statements): VERIFY after apply (read-only)
-- GENERATED by ops/seo-repairs-2026-11/db-change/generate.py - do not edit by hand; edit the CSVs and regenerate.
-- inputs:
--   fees/fee-corrections.csv  sha256 84726925a996bed6142f3c9bdb5b42a6cb5649535a8ad7bdc2c7d66034ef5adb
--   links/link-mapping.csv    sha256 ef178c31e10be760061031502c050da62ac64fdbd78cfcb725cddb1053fc35a6
-- fee rules: 2724 (action FIX, one per CSV row) on 2334 fields
-- link rules: 514 (REWRITE 393, UNLINK 121) - targets with at least one database row; expected counts from
--   content_pages / blog_posts link counts recomputed 2026-11-15 ~22:04 UTC (links/README.md)
-- link columns: content_pages.content, content_pages.body_markdown, blog_posts.content
-- field md5 pins: NO - apply.sql refuses to run until regenerated with --pins (PENDING-READS.md P1)
-- field guard: a field is changed only when md5(field) equals its pin; otherwise it is skipped and logged
-- count guard: link rule |fields holding the target now (pin-matching to change + insurance-skipped) + already applied
--              - expected| <= 2 + floor(5% of expected); fee rules together <= 2 + floor(2% of 2724)
-- run right after apply, again about an hour later and the next day:
--   psql -X -1 -v ON_ERROR_STOP=1 -f verify.sql > verify-<ts>.txt
-- =====================================================================================================

select to_regclass('public.seo_repair_change_log') is not null as seo_has_change_log \gset
\if :seo_has_change_log
\echo '=== repaired fields whose current value differs from the value the repair wrote (expect 0 rows) ==='
with last as (
  select distinct on (table_name, row_id, column_name) table_name, row_id, column_name, slug, new_md5, run_id
  from public.seo_repair_change_log where rolled_back_at is null
  order by table_name, row_id, column_name, id desc
)
select l.table_name, l.slug, l.column_name, l.run_id,
       case when c.id is null and b.id is null then 'row gone' else 'value changed after the repair' end as state
from last l
left join public.content_pages c on l.table_name = 'content_pages' and c.id = l.row_id::uuid
left join public.blog_posts b on l.table_name = 'blog_posts' and b.id = l.row_id::uuid
where md5(case l.table_name when 'content_pages' then (case l.column_name when $seo$body_markdown$seo$ then c.body_markdown when $seo$content$seo$ then c.content when $seo$description$seo$ then c.description when $seo$og_description$seo$ then c.og_description when $seo$seo_description$seo$ then c.seo_description when $seo$seo_title$seo$ then c.seo_title end)
                            when 'blog_posts' then (case l.column_name when $seo$content$seo$ then b.content end) end)
      is distinct from l.new_md5
order by 1, 2, 3;
\echo '=== repaired fields: total / unchanged since the repair ==='
with last as (
  select distinct on (table_name, row_id, column_name) table_name, row_id, column_name, new_md5
  from public.seo_repair_change_log where rolled_back_at is null
  order by table_name, row_id, column_name, id desc
)
select count(*) as repaired_fields,
       count(*) filter (where md5(case l.table_name when 'content_pages' then (case l.column_name when $seo$body_markdown$seo$ then c.body_markdown when $seo$content$seo$ then c.content when $seo$description$seo$ then c.description when $seo$og_description$seo$ then c.og_description when $seo$seo_description$seo$ then c.seo_description when $seo$seo_title$seo$ then c.seo_title end)
                            when 'blog_posts' then (case l.column_name when $seo$content$seo$ then b.content end) end) = l.new_md5)
         as unchanged_since_repair
from last l
left join public.content_pages c on l.table_name = 'content_pages' and c.id = l.row_id::uuid
left join public.blog_posts b on l.table_name = 'blog_posts' and b.id = l.row_id::uuid;
\else
\echo '=== no change log table: apply never committed ==='
\endif
